pitfalls.badSnippet:
// Unsafe traversal without null check
while (i < targetIndex) {
  current = current.next; // Throws TypeError if targetIndex > list.length
  i++;
}

pitfalls.goodSnippet:
// Safe traversal with guard condition
while (current && i < targetIndex) {
  current = current.next;
  i++;
}

pitfalls.badSnippet:
// Directly advancing head pointer
function traverse(head) {
  while (head) {
    console.log(head.value);
    head = head.next; // Destroys access to earlier nodes!
  }
}

pitfalls.goodSnippet:
// Always copy head to a temporary cursor variable
function traverse(head) {
  let current = head;
  while (current) {
    console.log(current.value);
    current = current.next;
  }
}
